#define MONSTER_CARD_COUNT (sizeof(kMonsterCards)/sizeof(kMonsterCards[0]))

inline const MonsterCard* FindMonsterCard(const char* uEm) {
    if (!uEm || !uEm[0]) return 0;
    for (size_t i = 0; i < MONSTER_CARD_COUNT; ++i)
        if (kMonsterCards[i].uEm && !strcmp(kMonsterCards[i].uEm, uEm))
            return &kMonsterCards[i];
    return 0;
}
